={
  "model": "openai/gpt-oss-120b",
  "temperature": 0.3,
  "messages": [
    {
      "role": "system",
      "content": "You are a lead classification engine for a healthcare clinic. Analyze customer inquiries and classify them. Respond ONLY with valid JSON."
    },
    {
      "role": "user",
      "content": "Classify this inquiry from {{ $json.contact_name }} (channel: {{ $json.channel }}): \"{{ $json.raw_message }}\"\n\nRespond with ONLY this JSON structure, no markdown:\n{\n  \"intent\": \"faq|pricing|booking|complaint|screening_info|other\",\n  \"urgency\": \"low|medium|high\",\n  \"lead_score\": <integer 0-100>,\n  \"summary\": \"<one sentence>\"\n}"
    }
  ]
}

parameters.jsCode:
const responseContent = $input.first().json.choices[0].message.content;

// Preserve original lead input (Groq response replaced it upstream)
const originalInput = $('When Executed by Another Workflow').first().json;

// Parse the JSON string from Groq
let classification;
try {
  classification = JSON.parse(responseContent);
} catch (e) {
  // Fallback if JSON parsing fails
  classification = {
    intent: "other",
    urgency: "medium",
    lead_score: 50,
    summary: "Classification failed — unable to parse response"
  };
}

// Validate required fields
const isValid = classification.intent && classification.urgency && 
  typeof classification.lead_score === 'number' && classification.summary;

return {
  json: {
    ...originalInput,
    ...classification,
    valid: isValid,
    raw_response: responseContent
  }
};

parameters.query:
INSERT INTO ai_decisions (lead_id, intent, urgency, lead_score, raw_prompt, raw_response)
VALUES ($1, $2, $3, $4, $5, $6)
RETURNING id;
